import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    b = []
    for _ in range(m):
        b.append(int(next(iterator)))

    MOD = 998244353

    if m > n:
        print(0)
        return

    current_idx = 0
    ways = 1

    for i in range(m):
        target = b[i]

        found = False
        count = 0

        while current_idx < n:
            val = a[current_idx]

            if val < target:
                print(0)
                return

            if val == target:
                found = True
                count += 1

            current_idx += 1

            if found and (current_idx >= n or a[current_idx] < b[i+1] if i+1 < m else True):
                break

        if not found:
            print(0)
            return

        if i < m - 1:
            next_target = b[i+1]
            if current_idx >= n:
                print(0)
                return

            while current_idx < n and a[current_idx] < next_target:
                current_idx += 1

            if current_idx >= n:
                if i < m - 1:
                    print(0)
                    return
            else:
                if a[current_idx] != next_target:
                    pass

            if current_idx < n:
                if a[current_idx] < next_target:
                    print(0)
                    return
        else:
            if current_idx != n:
                print(0)
                return

        if i < m - 1:
            ways = (ways * count) % MOD

    print(ways)

if __name__ == '__main__':
    solve()
